package net.townymap.gui;
import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.text.Text;import net.townymap.model.VotePartyStatus;
public final class VotePartyOverlay{private VotePartyOverlay(){}public static void renderMenu(DrawContext g,int sw,int sh,VotePartyStatus s,boolean loading,Screen screen){render(g,sw,8,s,loading);}public static void renderWorldMap(DrawContext g,int sw,VotePartyStatus s,boolean loading){render(g,sw,8,s,loading);}public static boolean renderBesideMinimap(DrawContext g,int center,int top,int bottom,int sw,VotePartyStatus s,boolean loading){if(s==null&&!loading)return false;var mc=MinecraftClient.getInstance();Text text=text(s);int w=mc.textRenderer.getWidth(text)+14,size=Math.max(1,bottom-top),left=center-size/2,x=left+size+8;if(x+w+2>sw)x=left-w-8;if(x<4)x=Math.max(4,sw-w-4);draw(g,x,top,s,text);return true;}private static void render(DrawContext g,int sw,int y,VotePartyStatus s,boolean loading){if(s==null&&!loading)return;Text text=text(s);int w=MinecraftClient.getInstance().textRenderer.getWidth(text)+14;draw(g,Math.max(4,(sw-w)/2),y,s,text);}private static Text text(VotePartyStatus s){return s==null?Text.translatable("townymapaddon.voteparty.loading"):Text.translatable("townymapaddon.voteparty.remaining",s.remaining(),s.percent());}private static void draw(DrawContext g,int x,int y,VotePartyStatus s,Text text){var tr=MinecraftClient.getInstance().textRenderer;int w=tr.getWidth(text)+14;g.fill(x-1,y-1,x+w+1,y+17,0xFF344047);g.fill(x,y,x+w,y+16,0xE810171B);if(s!=null)g.fill(x+1,y+14,x+1+(int)Math.round((w-2)*s.percent()/100d),y+16,0xFF55CC88);g.drawText(tr,text,x+7,y+4,s==null?0xFFFFCC66:0xFFFFFFFF,false);}}
